add('power','eu_conversion','EU, FE, J and conversion policy',[
 p('Calculator stores FE internally. Native adapters accept or send supported external units at the boundary. EU is therefore an accepted connection type, not a replacement for the internal buffer.'),
 table('Electrical adapters',('NeoForge FE','Native FE input/output. RF/IF/CF branding is compatible only where that mod exposes FE.'),('GregTech CEu','EU packets with voltage and amperage limits; separate native battery rules.'),('Mekanism','Joules via native machine and item APIs.'),('Modern Industrialization','EU via the MI energy API.'),('GrandPower','Long-valued FE API with a 1:1 base unit.'),('Applied Energistics 2','AE-powered items only; not a direct native grid port.')),
 p('Each native adapter has independent block-port and item-charging gates, input/output gates, and applicable loss settings. Input means native energy enters Foundations storage, including discharging an external battery. Output means Foundations energy leaves storage, including charging an external battery.'),
 table('Ratio keys',('compat.gtceu.fePerEU','0 inherits the higher of GT direction ratios; a positive integer fixes FE per EU.'),('power.mekanism.joulesPerFE','0 inherits Mekanism; a positive decimal fixes J per FE.'),('power.modernIndustrialization.fePerEU','0 inherits MI; a positive decimal fixes FE per EU.'),('compat.aeEnergyToFE','FE per AE for powered items.')),
 p('Voltage is packet size and amperage is packet count per tick. Neither is the EU/FE exchange rate. Port capacity, side modes, native item tier restrictions and shared packet budgets still apply.'),
 live('power','Effective server adapters, ratios, losses and warnings'),link('power/rounding','Whole units, losses and conversion loops'),link('power/gregtech','GregTech packet rules'),link('power/routing','Which API does a connection use?')
],keywords=['EU','FE','J','joules','voltage','conversion','Mekanism','GregTech','MI','AE2'])
