# Exact default greenhouse maps generated by executing the production blueprint against isolated coordinate fixtures.
by=collections.defaultdict(dict)
for line in (P/'docs/guide/blueprint-export.tsv').read_text().splitlines():
 tier,face,x,y,z,kind,meta=line.split('\t')
 if face=='NORTH':by[int(tier)][(int(x),int(y),int(z))]=kind
for tier,slug,label in [(1,'basic_greenhouse','Basic'),(2,'advanced_greenhouse','Advanced')]:
 data=by[tier];counts=collections.Counter(data.values());xs=[p[0] for p in data];ys=[p[1] for p in data];zs=[p[2] for p in data]
 blocks=[p(f'The {label} controller constructs this imported blueprint with Build. Its first four inputs are logs, wooden stairs, glass, and planks, in that order. Fill those slots, supply FE, and remove obstructions. Construction resumes where it stopped.'),
 table('Exact default structural materials (controller, floor, water and seeds are additional)',('Logs',str(counts['LOG'])),('Wooden stairs',str(counts['STAIRS'])),('Glass',str(counts['GLASS'])),('Planks',str(counts['PLANKS'])),('Unique structural blocks',str(len(data)))),
 p(f'Clear side {min(xs)} to {max(xs)}, inside {min(zs)} to {max(zs)}, and height {min(ys)} to {max(ys)}. The diagrams below show structural blocks only. C is the existing controller; dots are not a request to replace terrain.'),
 p('Provide dirt/grass beneath the growing cells. Basic has eight crops in its 3×3 area with central water; Advanced has 45 crops in a 7×7 area with four irrigation corners. Roof stairs are oriented by automatic construction, so supply stairs rather than placing a flat slab roof.'),
 note('R7 owner/protection preflights still apply. Missing owner, denied target, unloaded chunk or obstruction can stop a build. Never bypass a claim merely to complete a diagram. Demolish only recovers matching blocks after removal succeeds.')]
 for y in range(min(ys),max(ys)+1):
  rows=[]
  for z in range(min(zs),max(zs)+1):
   row=''
   for x in range(min(xs),max(xs)+1):row+=('C' if (x,y,z)==(0,0,0) else {'LOG':'L','STAIRS':'T','GLASS':'G','PLANKS':'P'}.get(data.get((x,y,z)),'.'))
   rows.append([row])
  blocks.append(block('layers',f'Height {y}; inside increases downward',rows=rows,legend='L logs · T stairs · G glass · P planks · C controller'))
 blocks += [live('machine/'+slug),link('farming/growing','Planting and greenhouse operation'),link('troubleshooting/construction','Construction stopped')]
 add('multiblocks',slug,label+' Greenhouse: complete default layers',blocks,keywords=['blueprint','roof','stairs','dimensions','material list'])
